ioc-container.pseudocode:
class Container:
    def __init__(self, defs):
        self.defs = defs  # 이름 → (클래스, 의존 빈 이름들)
        self.singletons = {}

    def get(self, name):
        if name in self.singletons:  # 싱글톤 스코프 재사용
            return self.singletons[name]
        cls, deps = self.defs[name]
        # 의존 빈을 먼저 재귀 생성 (그래프 순서)
        args = [self.get(d) for d in deps]
        bean = cls(*args)  # 생성자 주입
        self.singletons[name] = bean
        return bean
